import type { BankQuestion } from "@/lib/bank";

/** Oscillations and Waves (Physics (JEE/NEET)): 118 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-shm-waves-1","question":"The mass of the bob of a simple pendulum is doubled, keeping its length unchanged. For small oscillations its time period:","options":["becomes √2 times","doubles","halves","remains the same"],"answer":3,"explanation":"T = 2π√(l/g) contains no mass, so the period is unchanged. Only the length and the value of g matter.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-shm-waves-2","question":"In a stationary (standing) wave, the distance between two consecutive nodes is:","options":["λ/4","λ/2","λ","2λ"],"answer":1,"explanation":"Nodes (and antinodes) repeat every half wavelength; a node and the next antinode are λ/4 apart.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-shm-waves-3","question":"The mass attached to a spring is made four times. The time period of its oscillations becomes:","options":["4 times","2 times","√2 times","1/2 times"],"answer":1,"explanation":"T = 2π√(m/k) ∝ √m, so quadrupling m doubles the period.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-shm-waves-4","question":"A particle executes SHM given by x = 0.05 sin(10t) metre (t in seconds). Its maximum acceleration is:","options":["0.5 m/s²","0.05 m/s²","5 m/s²","50 m/s²"],"answer":2,"explanation":"a_max = Aω² = 0.05 × 10² = 5 m/s². 0.5 m/s (Aω) is the maximum speed, not acceleration.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-shm-waves-5","question":"A block on a spring of constant k oscillates with period T. If it is instead attached to two such springs joined end to end (in series), the period becomes:","options":["T/2","T/√2","2T","√2 T"],"answer":3,"explanation":"In series k_eq = k/2, and T ∝ 1/√k, so the period becomes √2 T. For two springs in parallel (2k) it would be T/√2.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-shm-waves-6","question":"A wave is described by y = 0.02 sin(4πt − 0.5πx) in SI units. The speed of the wave is:","options":["8 m/s","0.125 m/s","2 m/s","4 m/s"],"answer":0,"explanation":"v = ω/k = 4π/0.5π = 8 m/s. Dividing k by ω gives the reciprocal, 0.125.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-shm-waves-7","question":"Taking the speed of sound as 340 m/s, the fundamental frequency of a pipe 50 cm long that is closed at one end is:","options":["340 Hz","680 Hz","170 Hz","85 Hz"],"answer":2,"explanation":"For a closed pipe f = v/4L = 340/(4 × 0.5) = 170 Hz. 340 Hz is the fundamental of an open pipe of the same length (v/2L).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-shm-waves-8","question":"A string has tension 100 N and linear mass density 0.01 kg/m. The speed of transverse waves on it is:","options":["31.6 m/s","1000 m/s","10 m/s","100 m/s"],"answer":3,"explanation":"v = √(T/μ) = √(100/0.01) = √(10⁴) = 100 m/s.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-shm-waves-9","question":"For a particle in SHM of amplitude A, the fraction of its total energy that is kinetic when the displacement is A/2 is:","options":["1/√2","3/4","1/4","1/2"],"answer":1,"explanation":"K = ½k(A² − x²) and E = ½kA², so K/E = 1 − x²/A² = 1 − 1/4 = 3/4. 1/4 is the potential-energy fraction.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-shm-waves-10","question":"A tuning fork A of frequency 256 Hz produces 4 beats per second with fork B. When a little wax is stuck on B, the beat frequency becomes 6 per second. The original frequency of B was:","options":["250 Hz","252 Hz","260 Hz","262 Hz"],"answer":1,"explanation":"B is either 252 or 260 Hz. Wax lowers B's frequency; if B were 260 Hz the beats would first fall below 4, but they rose to 6, so B was 252 Hz (it drops to 250 Hz).","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-shm-waves-11","question":"A simple pendulum has period T in a stationary lift. If the lift accelerates downward with acceleration g/4, the period becomes:","options":["T","2T/√3","2T","√3T/2"],"answer":1,"explanation":"Effective g = g − g/4 = 3g/4. T ∝ 1/√g_eff, so T' = T√(4/3) = 2T/√3. Upward acceleration would shorten the period instead.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-shm-waves-12","question":"A source of sound of frequency 500 Hz moves towards a stationary observer at 34 m/s. If the speed of sound is 340 m/s, the frequency heard is about:","options":["556 Hz","550 Hz","450 Hz","455 Hz"],"answer":0,"explanation":"For a moving source f' = f·v/(v − vₛ) = 500 × 340/306 ≈ 556 Hz. 550 Hz is the result for an observer moving at 34 m/s towards a stationary source (f(v + v₀)/v), which is not the same.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-13","question":"The first overtone of a pipe closed at one end, of length 30 cm, is in unison with the fundamental of an open pipe. The length of the open pipe is:","options":["15 cm","20 cm","40 cm","45 cm"],"answer":1,"explanation":"First overtone of the closed pipe = 3v/4L_c; fundamental of the open pipe = v/2L_o. Equating: L_o = 4L_c/6 = 2 × 30/3 = 20 cm.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-14","question":"A particle in SHM has speed 8 cm/s when its displacement is 3 cm and speed 6 cm/s when its displacement is 4 cm. The amplitude of its motion is:","options":["5 cm","4 cm","7 cm","6 cm"],"answer":0,"explanation":"v² = ω²(A² − x²): 64 = ω²(A² − 9) and 36 = ω²(A² − 16). Subtracting gives 28 = 7ω², so ω = 2 rad/s, and A² = 9 + 64/4 = 25, A = 5 cm.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-shm-waves-15","question":"A particle executes SHM of period T starting from the mean position. The minimum time it takes to reach half of its amplitude is:","options":["T/6","T/8","T/12","T/4"],"answer":2,"explanation":"x = A sin(2πt/T) = A/2 → 2πt/T = π/6 → t = T/12. T/6 is the time from an extreme to the half-amplitude point.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-shm-waves-16","question":"A string fixed at both ends vibrates in 4 loops at 400 Hz. Keeping the frequency and length the same, the tension is changed so that it vibrates in 2 loops. The tension must be made:","options":["4 times","1/2 times","1/4 times","2 times"],"answer":0,"explanation":"With half the loops, λ doubles; at fixed frequency v = fλ also doubles. Since v ∝ √T, the tension must become 4 times.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-17","question":"A uniform rod of length L oscillates in a vertical plane about a horizontal axis through one end. Its period of small oscillations is:","options":["2π√(3L/2g)","2π√(L/g)","2π√(L/2g)","2π√(2L/3g)"],"answer":3,"explanation":"For a physical pendulum T = 2π√(I/mgd) with I = mL²/3 and d = L/2: T = 2π√(2L/3g). Treating it as a simple pendulum of length L ignores the distributed mass.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-18","question":"If the sound level at a point increases by 20 dB, the intensity of the sound there becomes:","options":["2 times","100 times","20 times","10 times"],"answer":1,"explanation":"ΔL = 10 log(I₂/I₁) = 20 dB → I₂/I₁ = 10² = 100. Each 10 dB is a factor of 10, so 20 dB is not 20 times.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-shm-waves-19","question":"A spring of constant k is cut into two pieces whose lengths are in the ratio 1 : 2. A mass m is attached to the two pieces connected in parallel. If T₀ is the period of m on the original uncut spring, the new period is:","options":["2T₀/3","√2 T₀/3","T₀/√3","3T₀/√2"],"answer":1,"explanation":"k ∝ 1/length, so the pieces have constants 3k and 3k/2. In parallel k_eq = 4.5k, and T = 2π√(m/4.5k) = T₀/√4.5 = √2 T₀/3.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-20","question":"A 0.5 kg block rests on a 1.5 kg block that is attached to a horizontal spring of constant 200 N/m on a frictionless floor. The coefficient of static friction between the blocks is 0.4 (g = 10 m/s²). The maximum amplitude of oscillation for which the upper block does not slip is:","options":["3 cm","2 cm","4 cm","1 cm"],"answer":2,"explanation":"ω² = k/(M + m) = 200/2 = 100 s⁻². The top block needs friction m·ω²A ≤ μmg, so A ≤ μg/ω² = 4/100 m = 4 cm.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-21","question":"A source and an observer approach each other, each moving at 20 m/s. The source emits 600 Hz and the speed of sound is 340 m/s. The frequency heard by the observer is:","options":["675 Hz","533 Hz","640 Hz","600 Hz"],"answer":0,"explanation":"f' = f(v + v₀)/(v − vₛ) = 600 × 360/320 = 675 Hz. Moving apart at the same speeds would give 600 × 320/360 ≈ 533 Hz.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-22","question":"A car moves towards a large wall at 30 m/s while sounding a horn of 500 Hz. Taking the speed of sound as 330 m/s, the frequency of the echo heard by the driver is:","options":["550 Hz","545 Hz","600 Hz","500 Hz"],"answer":2,"explanation":"The wall receives f₁ = 500 × 330/300 = 550 Hz and reflects it as a stationary source. The driver moving towards it hears 550 × 360/330 = 600 Hz. Equivalently f'' = f(v + u)/(v − u) = 500 × 1.2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-23","question":"Two open organ pipes of lengths 50 cm and 51 cm, sounding their fundamentals together, produce 6 beats per second. The speed of sound is:","options":["306 m/s","340 m/s","312 m/s","330 m/s"],"answer":0,"explanation":"v/(2 × 0.50) − v/(2 × 0.51) = 6 → v(1 − 1/1.02) = 6 → v × 0.02/1.02 = 6 → v = 306 m/s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-24","question":"How many of the following statements about a stationary wave on a string are correct?\n(A) There is no net transport of energy along the string.\n(B) All particles between two adjacent nodes vibrate in phase.\n(C) All particles vibrate with the same amplitude.\n(D) Particles on opposite sides of a node vibrate in opposite phase.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and D are correct. C is wrong: the amplitude varies from zero at the nodes to a maximum at the antinodes (it is a progressive wave in which every particle has the same amplitude). So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-shm-waves-25","question":"A particle is subjected simultaneously to two SHMs along the same line: x₁ = 3 sin ωt and x₂ = 4 sin(ωt + π/3) (in cm). The amplitude of the resultant motion is:","options":["7 cm","√13 cm","√37 cm","5 cm"],"answer":2,"explanation":"A² = A₁² + A₂² + 2A₁A₂ cos φ = 9 + 16 + 24 × ½ = 37, so A = √37 cm. 5 cm would be for a phase difference of π/2 and √13 cm for 2π/3.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-26","question":"A liquid column of total length L in a uniform U-tube is depressed on one side and released. Neglecting viscosity, the period of its oscillations is:","options":["2π√(2L/g)","2π√(L/g)","π√(2L/g)","π√(L/g)"],"answer":2,"explanation":"A displacement x raises one side and lowers the other, so the restoring force is 2xAρg on a mass ALρ: ω² = 2g/L, giving T = 2π√(L/2g) = π√(2L/g).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-27","question":"A wave on a string is y = 0.03 sin 2π(t/0.04 − x/0.5) in SI units. The ratio of the maximum speed of a particle of the string to the speed of the wave is:","options":["0.24π","0.12π","0.06π","0.03π"],"answer":1,"explanation":"ω = 2π/0.04 = 50π rad/s and k = 2π/0.5 = 4π rad/m. Max particle speed / wave speed = Aω/(ω/k) = Ak = 0.03 × 4π = 0.12π.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-28","question":"Assertion (A): At the same temperature and pressure, sound travels faster in moist air than in dry air.\nReason (R): Water vapour has a lower molar mass than dry air, so moist air is less dense.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"v = √(γP/ρ); at the same P, moist air (M of water = 18 against about 29 for air) has lower density, so sound is faster. R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-shm-waves-29","question":"Two blocks of masses 1 kg and 3 kg are connected by a light spring of constant 300 N/m and placed on a frictionless floor. The blocks are pulled apart and released. The period of their oscillation is:","options":["π/5 s","π/10 s","2π/15 s","π/20 s"],"answer":1,"explanation":"Use the reduced mass μ = (1 × 3)/(1 + 3) = 0.75 kg. ω = √(k/μ) = √400 = 20 rad/s, so T = 2π/20 = π/10 s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-30","question":"Match the wave (List I) with the expression for its speed (List II). List I: (P) transverse wave on a stretched string; (Q) sound in a gas (Laplace); (R) longitudinal wave in a solid rod; (S) sound in a gas (Newton's original formula). List II: (1) √(Y/ρ); (2) √(γP/ρ); (3) √(T/μ); (4) √(P/ρ).","options":["P-3, Q-2, R-4, S-1","P-3, Q-4, R-1, S-2","P-3, Q-2, R-1, S-4","P-1, Q-2, R-3, S-4"],"answer":2,"explanation":"String: √(T/μ). Newton assumed isothermal compressions (√(P/ρ), about 280 m/s in air); Laplace corrected this to adiabatic, √(γP/ρ). A thin rod carries longitudinal waves at √(Y/ρ).","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-shm-waves-31", "question": "In simple harmonic motion, the phase difference between the displacement and the velocity of the particle is:", "options": ["zero", "π/2", "π", "π/4"], "answer": 1, "explanation": "If x = A sin ωt, then v = Aω cos ωt = Aω sin(ωt + π/2), so velocity leads displacement by π/2. Acceleration is π out of phase with displacement.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-shm-waves-32", "question": "Sound waves travelling through air are:", "options": ["transverse", "longitudinal", "electromagnetic", "partly transverse and partly longitudinal"], "answer": 1, "explanation": "In a gas, sound travels as compressions and rarefactions, with the air particles vibrating along the direction of propagation; gases cannot support transverse waves.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-shm-waves-33", "question": "The restoring force in simple harmonic motion is:", "options": ["proportional to displacement and directed away from the mean position", "constant in magnitude and directed towards the mean position", "proportional to displacement and directed towards the mean position", "proportional to velocity and opposite to it"], "answer": 2, "explanation": "SHM is defined by F = −kx: the force is proportional to the displacement and always points back towards the mean position. A force proportional to velocity is a damping force.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-shm-waves-34", "question": "Taking g = 10 m/s², the length of a seconds pendulum (period 2 s) is about:", "options": ["2 m", "0.5 m", "1 m", "0.25 m"], "answer": 2, "explanation": "l = gT²/(4π²) = 10 × 4/39.5 ≈ 1.01 m.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-shm-waves-35", "question": "The fundamental frequency of a pipe open at both ends is 200 Hz. The frequency of its second overtone is:", "options": ["400 Hz", "600 Hz", "1000 Hz", "500 Hz"], "answer": 1, "explanation": "An open pipe has all harmonics f, 2f, 3f, …; the second overtone is the third harmonic, 600 Hz. 1000 Hz (5f) would be the second overtone of a closed pipe with fundamental 200 Hz.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-shm-waves-36", "question": "The speed of sound in air at 27 °C is 340 m/s. Its speed at 127 °C is about:", "options": ["393 m/s", "453 m/s", "370 m/s", "680 m/s"], "answer": 0, "explanation": "v ∝ √T (kelvin): v = 340 × √(400/300) = 340 × 1.155 ≈ 393 m/s. Using the Celsius ratio 127/27 gives a wildly wrong answer.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-shm-waves-37", "question": "A mass on a spring of constant k oscillates with period T. If it is attached instead to two such springs connected in parallel, the period becomes:", "options": ["2T", "T/2", "√2 T", "T/√2"], "answer": 3, "explanation": "Springs in parallel add: k_eff = 2k, and T ∝ 1/√k, so the period becomes T/√2.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-shm-waves-38", "question": "The amplitude of a sound wave is doubled and its frequency is halved, all else remaining the same. Its intensity becomes:", "options": ["unchanged", "double", "four times", "half"], "answer": 0, "explanation": "Intensity ∝ A²ω²: (2)² × (½)² = 1, so the intensity does not change.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-shm-waves-39", "question": "A 1 kg block attached to a spring of constant 100 N/m oscillates on a smooth floor with amplitude 10 cm. At the position where its kinetic energy equals its potential energy, its speed is about:", "options": ["1 m/s", "0.71 m/s", "0.5 m/s", "0.35 m/s"], "answer": 1, "explanation": "Total energy = ½kA² = ½ × 100 × 0.01 = 0.5 J; when KE = PE each is 0.25 J, so ½ × 1 × v² = 0.25 and v = √0.5 ≈ 0.71 m/s.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-shm-waves-40", "question": "A simple pendulum has period T when the car carrying it is at rest. When the car accelerates horizontally at 10√3 m/s² (g = 10 m/s²), its period of small oscillations becomes:", "options": ["T/2", "T/√2", "√2 T", "T/√3"], "answer": 1, "explanation": "g_eff = √(g² + a²) = √(100 + 300) = 20 m/s² = 2g. Since T ∝ 1/√g_eff, the new period is T/√2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-41", "question": "A block hanging from a light spring stretches it by 2.5 cm at equilibrium. If the block is pulled down a little and released, its period of oscillation is (g = 10 m/s²):", "options": ["π/10 s", "π/5 s", "π/20 s", "π s"], "answer": 0, "explanation": "At equilibrium kx₀ = mg, so m/k = x₀/g and T = 2π√(x₀/g) = 2π√(0.025/10) = 2π × 0.05 = π/10 s ≈ 0.31 s.", "difficulty": "hard", "source": "NEET · JEE Main"},
  {"id": "phy-shm-waves-42", "question": "A stationary wave on a string is y = 5 sin(πx/3) cos(40πt), with x and y in cm and t in s. The distance between a node and the nearest antinode is:", "options": ["3 cm", "6 cm", "1.5 cm", "0.75 cm"], "answer": 2, "explanation": "k = π/3 cm⁻¹, so λ = 2π/k = 6 cm. A node and the adjacent antinode are λ/4 = 1.5 cm apart; 3 cm (λ/2) is node to node.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-43", "question": "A sonometer wire is kept taut by a solid block of relative density 4 hanging from it, and its fundamental frequency is f. When the hanging block is completely immersed in water, the fundamental frequency becomes:", "options": ["3f/4", "(√3/2) f", "f/2", "(2/√3) f"], "answer": 1, "explanation": "Buoyancy reduces the tension to T(1 − 1/4) = 3T/4, and f ∝ √T, so f' = √(3/4) f = (√3/2) f. 3f/4 forgets the square root.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-44", "question": "A wooden cylinder floats upright in water with 0.4 m of its length submerged. It is pressed down slightly and released. Neglecting viscosity, its period of vertical oscillation is (g = 10 m/s²):", "options": ["0.2π s", "0.4π s", "0.8π s", "0.1π s"], "answer": 1, "explanation": "Extra depth y gives an extra upthrust ρAgy, and the mass is ρAl (l = submerged length), so ω² = g/l and T = 2π√(l/g) = 2π√(0.04) = 0.4π s ≈ 1.26 s.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-45", "question": "The displacement of a particle is x = 3 sin 2t + 4 cos 2t, with x in cm and t in s. Its maximum speed is:", "options": ["14 cm/s", "10 cm/s", "7 cm/s", "5 cm/s"], "answer": 1, "explanation": "The two terms are in quadrature, so the amplitude is √(3² + 4²) = 5 cm and v_max = Aω = 5 × 2 = 10 cm/s. Adding amplitudes (7 cm) ignores the phase difference.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-shm-waves-46", "question": "A uniform disc of radius R oscillates in its own vertical plane about a horizontal axis through a point on its rim. Its period of small oscillations is:", "options": ["2π√(R/g)", "2π√(2R/g)", "2π√(R/2g)", "2π√(3R/2g)"], "answer": 3, "explanation": "About a rim point I = ½MR² + MR² = (3/2)MR², and the centre of mass is R from the axis, so T = 2π√(I/(MgR)) = 2π√(3R/2g).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-47", "question": "A pipe open at both ends has fundamental frequency f. It is now dipped vertically in water so that half its length is under water. The fundamental frequency of the air column is now:", "options": ["f/2", "2f", "f", "f/4"], "answer": 2, "explanation": "The air column becomes a closed pipe of length L/2, with fundamental v/(4 × L/2) = v/2L, which equals the original open-pipe fundamental f.", "difficulty": "hard", "source": "NEET · JEE Main"},
  {"id": "phy-shm-waves-48", "question": "In a damped oscillator, the amplitude falls to half its initial value in 10 s. The fraction of the initial mechanical energy that remains after 30 s is:", "options": ["1/8", "1/64", "1/27", "1/16"], "answer": 1, "explanation": "Amplitude decays exponentially, so after 30 s (three half-lives of amplitude) it is 1/8 of its first value. Energy ∝ A², so it is (1/8)² = 1/64; 1/8 is the amplitude, not the energy.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-49", "question": "In a resonance-tube experiment with a 500 Hz tuning fork, the first and second resonances occur at air-column lengths of 16 cm and 50 cm. The speed of sound and the end correction are respectively:", "options": ["340 m/s and 1 cm", "330 m/s and 0.5 cm", "340 m/s and 2 cm", "320 m/s and 1 cm"], "answer": 0, "explanation": "l₂ − l₁ = λ/2 = 34 cm, so λ = 68 cm and v = 500 × 0.68 = 340 m/s. With end correction e, l₁ + e = λ/4 = 17 cm, so e = 1 cm.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-shm-waves-50", "question": "How many of the following statements about the Doppler effect in sound are correct?\n(A) For the same relative speed of approach, the frequency heard depends on whether the source or the observer is moving.\n(B) When the source moves towards a stationary observer, the wavelength of the sound reaching the observer decreases.\n(C) When the observer moves towards a stationary source, the wavelength of the sound reaching him decreases.\n(D) A source approaching an observer and the same source receding at the same speed are heard at the same frequency.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and B are correct: the medium makes the two cases different, and a moving source crowds its wave-fronts. C is wrong (a moving observer meets waves of unchanged wavelength at a higher relative speed), and D is wrong since an approaching source sounds higher.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-shm-waves-51", "question": "Assertion (A): The period of a simple pendulum inside a satellite orbiting the Earth is infinite.\nReason (R): Inside the orbiting satellite the effective acceleration due to gravity is zero.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "In the freely falling satellite g_eff = 0, so there is no restoring torque and T = 2π√(l/g_eff) → ∞; the bob does not oscillate at all. R is exactly the reason for A.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-shm-waves-52", "question": "For an air column or string of length L and wave speed v, match each mode (List I) with its frequency (List II). List I: (P) fundamental of a pipe open at both ends; (Q) fundamental of a pipe closed at one end; (R) third harmonic of a string fixed at both ends; (S) first overtone of a pipe closed at one end. List II: (1) v/4L; (2) 3v/4L; (3) v/2L; (4) 3v/2L.", "options": ["P-3, Q-1, R-2, S-4", "P-1, Q-3, R-4, S-2", "P-3, Q-2, R-4, S-1", "P-3, Q-1, R-4, S-2"], "answer": 3, "explanation": "Open pipe and string: fₙ = nv/2L, so the open fundamental is v/2L and the string's third harmonic is 3v/2L. Closed pipe: v/4L, then 3v/4L as its first overtone. So P-3, Q-1, R-4, S-2.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-shm-waves-53", "question": "A block of mass M = 3m, attached to a horizontal spring on a smooth floor, oscillates with amplitude A. As it passes through its mean position, a lump of putty of mass m is dropped vertically onto it and sticks. The new amplitude is:", "options": ["A", "(√3/2)A", "3A/4", "A/2"], "answer": 1, "explanation": "Horizontal momentum is conserved: v' = Mv/(M + m) = 3v/4. The new ω' = √(k/4m) = (√3/2)ω, so A' = v'/ω' = (3Aω/4)/((√3/2)ω) = (√3/2)A. If the putty fell at an extreme position the amplitude would stay A.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-shm-waves-54", "question": "A uniform rope of length 10 m hangs vertically from a rigid support. A small transverse pulse is produced at its lower end. The time it takes to reach the top is (g = 10 m/s²):", "options": ["1 s", "√2 s", "2 s", "4 s"], "answer": 2, "explanation": "At height y above the free end the tension supports the rope below, T = μgy, so v = √(T/μ) = √(gy). Then t = ∫dy/√(gy) = 2√(L/g) = 2√(10/10) = 2 s.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-shm-waves-55", "question": "The displacement of a particle is x = a sin²(ωt). Its motion is:", "options": ["not periodic", "periodic but not simple harmonic", "SHM of amplitude a and period 2π/ω", "SHM of amplitude a/2 and period π/ω"], "answer": 3, "explanation": "a sin²ωt = a/2 − (a/2) cos 2ωt: an SHM of amplitude a/2 about x = a/2, with angular frequency 2ω and period π/ω.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-56", "question": "A whistle of frequency 540 Hz is whirled in a horizontal circle of radius 2 m at an angular speed of 15 rad/s. Taking the speed of sound as 330 m/s, the highest and lowest frequencies heard by a listener far away at rest in the plane of the circle are:", "options": ["594 Hz and 495 Hz", "594 Hz and 486 Hz", "570 Hz and 510 Hz", "600 Hz and 490 Hz"], "answer": 0, "explanation": "Source speed = rω = 30 m/s. Approaching: 540 × 330/300 = 594 Hz; receding: 540 × 330/360 = 495 Hz. 486 Hz uses the moving-observer formula for the receding case.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-57", "question": "Two particles execute SHM along the same line with the same amplitude A and frequency about the same mean position. They pass each other moving in opposite directions when each is at a displacement A/2. Their phase difference is:", "options": ["π/3", "π/2", "2π/3", "π"], "answer": 2, "explanation": "x = A sin φ = A/2 gives φ = π/6 for the one moving in the positive direction and 5π/6 for the one moving back. The phase difference is 5π/6 − π/6 = 2π/3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-58", "question": "A transverse wave y = 0.02 sin(20x − 400t) (SI units) travels on a string of linear mass density 0.05 kg/m. The average power transmitted by the wave is:", "options": ["16 W", "64 W", "32 W", "8 W"], "answer": 2, "explanation": "Wave speed v = ω/k = 400/20 = 20 m/s. P = ½μω²A²v = ½ × 0.05 × (400)² × (0.02)² × 20 = ½ × 0.05 × 160000 × 0.0004 × 20 = 32 W.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-59", "question": "A 1 kg block is attached to a uniform spring of mass 0.3 kg and spring constant 110 N/m on a smooth floor. Taking the spring's mass into account, the period of oscillation is about:", "options": ["0.60 s", "0.69 s", "0.57 s", "0.63 s"], "answer": 3, "explanation": "A uniform spring adds one-third of its mass: T = 2π√((M + m_s/3)/k) = 2π√(1.1/110) = 2π × 0.1 ≈ 0.63 s. Ignoring the spring gives 0.60 s; adding its full mass gives 0.69 s.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-shm-waves-60", "question": "A pipe 85 cm long is closed at one end. Taking the speed of sound as 340 m/s, how many of its natural frequencies lie below 1250 Hz?", "options": ["4", "5", "6", "12"], "answer": 2, "explanation": "Fundamental = v/4L = 340/3.4 = 100 Hz, and a closed pipe has only odd harmonics: 100, 300, 500, 700, 900, 1100 Hz below 1250 Hz, i.e. 6. Counting all multiples of 100 Hz would give 12.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-shm-waves-61","question":"A sound wave of frequency 500 Hz travels at 350 m/s. The phase difference between two points on its line of travel that are 17.5 cm apart is:","options":["π/2","π","π/4","2π/5"],"answer":0,"explanation":"λ = 350/500 = 0.70 m. Δφ = 2πΔx/λ = 2π × 0.175/0.70 = π/2. π comes from taking the separation as half a wavelength.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-62","question":"At the same temperature, the ratio of the speed of sound in hydrogen to that in oxygen (both diatomic) is:","options":["16 : 1","4 : 1","1 : 4","2 : 1"],"answer":1,"explanation":"v = √(γRT/M); with the same γ and T, v ∝ 1/√M, so v_H₂/v_O₂ = √(32/2) = 4. 16 : 1 forgets the square root.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-63","question":"A sonometer wire is in unison with a 400 Hz tuning fork. The tension in the wire is then increased by 1%, everything else unchanged. The number of beats heard per second is about:","options":["4","1","2","8"],"answer":2,"explanation":"f ∝ √T, so a 1% rise in tension raises f by about 0.5%: 0.005 × 400 = 2 Hz, giving 2 beats per second. 4 beats per second assumes f ∝ T.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-64","question":"A simple pendulum of length 1 m hangs from the roof of a trolley that slides freely down a smooth plane inclined at 60° (g = 10 m/s²). Its period of small oscillations is about:","options":["1.99 s","1.40 s","2.14 s","2.81 s"],"answer":3,"explanation":"The trolley accelerates down the slope at g sin 60°, so in its frame the effective gravity is g cos 60° = 5 m/s², perpendicular to the incline. T = 2π√(1/5) ≈ 2.81 s. Using g sin 60° gives 2.14 s; ignoring the motion gives 1.99 s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-65","question":"A particle is acted on simultaneously by two perpendicular SHMs, x = A sin ωt and y = A sin 2ωt. Its path is:","options":["A figure-of-eight","A circle","An ellipse","A straight line"],"answer":0,"explanation":"With a 1 : 2 frequency ratio, y = 2A sin ωt cos ωt = 2x√(1 − x²/A²) up to sign, which traces a figure-of-eight (a Lissajous figure with two lobes). Equal frequencies with a 90° phase difference would give a circle or an ellipse.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-66","question":"A particle executes SHM of period T starting from the mean position. The least time after which its kinetic energy equals its potential energy is:","options":["T/4","T/8","T/6","T/12"],"answer":1,"explanation":"K = U when x = A/√2, i.e. sin ωt = 1/√2, ωt = π/4, so t = T/8. T/12 is the time to reach A/2, the common confusion.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-67","question":"A uniform rope of mass m hangs from a ceiling with a block of mass 2m tied to its lower end. The ratio of the speed of a transverse pulse at the top of the rope to its speed at the bottom is:","options":["√2","3/2","√(3/2)","√3"],"answer":2,"explanation":"v = √(T/μ). The tension is 3mg at the top (rope plus block) and 2mg at the bottom (block alone), so v_top/v_bottom = √(3/2). 3/2 forgets the square root.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-68","question":"Two incoherent sources each produce a sound level of 80 dB at a point. With both sources sounding together, the sound level at the point is about:","options":["160 dB","86 dB","80 dB","83 dB"],"answer":3,"explanation":"Incoherent intensities add: I = 2I₀, so L = 80 + 10 log₁₀2 ≈ 83 dB. Decibels do not add (160 dB is wrong); 86 dB would correspond to 4I₀, which only happens at a point of constructive interference of coherent sources.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-69","question":"A stationary wave is formed by two waves, each of amplitude A. The amplitude of vibration at a point λ/8 from a node is:","options":["√2 A","2A","A/√2","A"],"answer":0,"explanation":"In a stationary wave the amplitude is 2A |sin kx| measured from a node. At x = λ/8, kx = π/4, so the amplitude is 2A × (1/√2) = √2 A. 2A is the amplitude at an antinode (λ/4 from a node).","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-shm-waves-70", "question": "A pipe 25 cm long, closed at one end, sounds its fundamental (speed of sound 340 m/s). A wire 50 cm long with a linear mass density of 1 g/m, fixed at both ends, resonates with it in the wire's own fundamental mode. The tension in the wire is about:", "options": ["29 N", "116 N", "462 N", "58 N"], "answer": 1, "explanation": "Closed pipe: f = v/4L = 340/1.0 = 340 Hz. Wire: f = (1/2l)√(T/μ), so √(T/μ) = 2 × 0.5 × 340 = 340 m/s and T = 10⁻³ × 340² ≈ 116 N. Treating the pipe as open (f = 680 Hz) gives 462 N.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-71", "question": "A uniform rod 1.2 m long is made to oscillate as a compound pendulum about a horizontal axis perpendicular to it. The pivot is placed so that the period is as small as possible (g = 10 m/s²). This least period is about:", "options": ["1.78 s", "1.26 s", "1.65 s", "2.18 s"], "answer": 2, "explanation": "T = 2π√((L²/12 + x²)/(gx)) for a pivot x from the centre, least when x = L/√12 ≈ 0.346 m, where T = 2π√(2x/g) ≈ 1.65 s. With the pivot at one end, T = 2π√(2L/3g) ≈ 1.78 s, which is not the least.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-shm-waves-72","question":"A particle moves along the x-axis in a potential U = k|x| (k a positive constant). If its amplitude of oscillation is A, its period varies as:","options":["1/√A","A","A⁰ (it does not depend on A)","√A"],"answer":3,"explanation":"The force is a constant k towards the origin, so each quarter is uniform acceleration a = k/m over the distance A: A = ½(k/m)t², t ∝ √A, and T = 4t ∝ √A. Independence of amplitude holds only for a linear restoring force (SHM).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-shm-waves-73", "question": "A block of mass m hangs from a light frictionless pulley. A light string passes under the pulley; one end is fixed to the ceiling and the other is tied to the lower end of a vertical spring of constant k whose upper end is fixed to the ceiling. The period of small vertical oscillations of the block is:", "options": ["π√(m/k)", "2π√(m/k)", "4π√(m/k)", "π√(m/2k)"], "answer": 0, "explanation": "If the block moves down x, each side of the string lengthens by x, so the spring stretches 2x and the tension rises by 2kx. Both segments pull on the pulley: restoring force 4kx, so k_eff = 4k and T = 2π√(m/4k) = π√(m/k). 4π√(m/k) comes from k_eff = k/4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-74", "question": "How many of the following statements about damped and forced oscillations are correct?\n(A) In the steady state, a forced oscillator vibrates at the frequency of the driving force, not at its own natural frequency.\n(B) The lighter the damping, the taller and sharper the resonance peak.\n(C) For a lightly damped oscillator the amplitude decays exponentially, and the energy decays with twice the decay constant.\n(D) At velocity resonance, the velocity of the oscillator is in phase with the driving force.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 2, "explanation": "All four are correct. In D, it is the velocity, not the displacement, that is in phase with the force at resonance (the displacement lags by π/2); this is why the driver then delivers power most efficiently.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-shm-waves-75", "question": "Two waves y₁ = A sin(kx − ωt) and y₂ = A sin(kx + ωt + π/3) travel on the same string. The nearest node to x = 0 on the positive x side lies at:", "options": ["x = λ/2", "x = 5λ/12", "x = λ/12", "x = λ/3"], "answer": 1, "explanation": "y₁ + y₂ = 2A sin(kx + π/6) cos(ωt + π/6). Nodes need sin(kx + π/6) = 0, i.e. kx = nπ − π/6; the first positive one is kx = 5π/6, x = 5λ/12. λ/2 ignores the π/3 phase, which shifts all the nodes by λ/12.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-shm-waves-76","question":"A string of linear density μ is joined to a second string of linear density 4μ under the same tension. A wave of amplitude A travels along the lighter string towards the joint. The amplitudes of the transmitted and reflected waves are:","options":["4A/3 transmitted; A/3 reflected, not inverted","A/3 transmitted; 2A/3 reflected and inverted","2A/3 transmitted; A/3 reflected and inverted","2A/3 transmitted; A/3 reflected, not inverted"],"answer":2,"explanation":"v ∝ 1/√μ, so v₂ = v₁/2. A_t = 2v₂A/(v₁ + v₂) = (1)/(1.5) A = 2A/3, and A_r = (v₂ − v₁)A/(v₁ + v₂) = −A/3: inverted, as at a denser (more rigid) boundary. A non-inverted reflection happens only going from heavy to light.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-77","question":"A source of 500 Hz moves at 50 m/s towards a stationary observer. A wind blows at 30 m/s from the observer towards the source. Taking the speed of sound in still air as 330 m/s, the frequency heard is:","options":["589 Hz","560 Hz","625 Hz","600 Hz"],"answer":3,"explanation":"The wind blows against the sound's direction of travel, so the sound moves at 330 − 30 = 300 m/s relative to the ground. f′ = f(v − w)/(v − w − v_s) = 500 × 300/250 = 600 Hz. Ignoring the wind gives 500 × 330/280 ≈ 589 Hz.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-shm-waves-78", "question": "A metal rod 1 m long is clamped at its midpoint, and longitudinal waves travel in it at 5000 m/s. Its fundamental frequency and the frequency of its next mode are:", "options": ["2500 Hz and 7500 Hz", "2500 Hz and 5000 Hz", "5000 Hz and 10 000 Hz", "1250 Hz and 3750 Hz"], "answer": 0, "explanation": "The clamp makes a node at the middle and the free ends are antinodes, so L = λ/2, 3λ/2, …: f = nv/(2L) with n odd only: 2500 Hz and 7500 Hz. Including even harmonics (5000 Hz) would need an antinode at the clamp.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-shm-waves-79","question":"A V-shaped tube has both arms inclined at 30° to the horizontal and contains a liquid column of total length 40 cm. When the liquid is disturbed, its period of small oscillations is about (g = 10 m/s²):","options":["0.89 s","1.26 s","0.63 s","1.78 s"],"answer":1,"explanation":"Displacing the liquid by x along the tube raises it by x sin α on one side and lowers it by x sin β on the other: restoring force ρAg x(sin α + sin β). Mass ρAL, so T = 2π√(L/(g(sin α + sin β))) = 2π√(0.4/10) ≈ 1.26 s. The vertical U-tube formula 2π√(L/2g) gives 0.89 s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-shm-waves-80", "question": "An observer moves at speed u along the line joining two identical sources of 340 Hz, towards one and away from the other. He hears 4 beats per second. If the speed of sound is 340 m/s, u is:", "options": ["4 m/s", "1 m/s", "2 m/s", "8 m/s"], "answer": 2, "explanation": "He hears f(v + u)/v from the source ahead and f(v − u)/v from the one behind. Beat frequency = 2fu/v = 4, so u = 4 × 340/(2 × 340) = 2 m/s. 4 m/s forgets that both frequencies shift.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-shm-waves-81","question":"Two identical blocks, each of mass m, are joined by a light spring of constant k on a smooth floor; the left block touches a wall. The right block is pushed to compress the spring by x₀ and released. After the left block leaves the wall, the greatest extension of the spring is:","options":["x₀","x₀/2","√2 x₀","x₀/√2"],"answer":3,"explanation":"At natural length the right block has v₀ = x₀√(k/m) and the left block leaves the wall. Afterwards momentum mv₀ is conserved; at maximum extension both move at v₀/2, keeping kinetic energy mv₀²/4. So ½kA² = ½mv₀² − ¼mv₀² gives A = x₀/√2. x₀ ignores the kinetic energy locked in the centre-of-mass motion.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-shm-waves-82", "question": "How many of the following statements about sound waves are correct?\n(A) In a longitudinal wave, a pressure node is a displacement antinode.\n(B) At constant temperature, the speed of sound in air does not depend on the pressure.\n(C) Sound travels more slowly in humid air than in dry air at the same temperature and pressure.\n(D) Transverse waves can travel through air.", "options": ["Only two", "Only one", "Only three", "All four"], "answer": 0, "explanation": "A and B are correct (v = √(γP/ρ), and P/ρ is fixed at constant T). C is wrong: water vapour lowers the mean molar mass, so sound is faster in humid air. D is wrong: a gas has no shear rigidity.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-shm-waves-83","question":"Match each pendulum (List I) with its period of small oscillations (List II). (L = length, R = radius of the Earth, g = surface gravity.)\nList I: (P) a simple pendulum in a freely falling lift; (Q) a simple pendulum of length equal to R; (R) a simple pendulum of infinite length; (S) a simple pendulum in a car accelerating horizontally at a.\nList II: (1) 2π√(R/g); (2) 2π√(R/2g); (3) it does not oscillate (infinite period); (4) 2π√(L/√(g² + a²)).","options":["P–3, Q–2, R–1, S–4","P–1, Q–2, R–3, S–4","P–3, Q–2, R–4, S–1","P–3, Q–1, R–2, S–4"],"answer":0,"explanation":"In free fall g_eff = 0, so there is no oscillation. For a long pendulum T = 2π√(1/(g(1/L + 1/R))): L = R gives 2π√(R/2g), and L → ∞ gives 2π√(R/g) ≈ 84 minutes. In the accelerating car g_eff = √(g² + a²).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-shm-waves-84", "question": "Two loudspeakers are driven by the same oscillator but connected in opposite phase. A listener is 4.0 m from one speaker and 4.5 m from the other. Taking the speed of sound as 340 m/s, the lowest frequency for which the listener hears silence is:", "options": ["340 Hz", "680 Hz", "1020 Hz", "170 Hz"], "answer": 1, "explanation": "The sources start π out of phase, so silence needs the path difference to be a whole number of wavelengths: 0.5 = nλ. The longest λ is 0.5 m, so f = 340/0.5 = 680 Hz. For in-phase speakers, Δ = λ/2 would give 340 Hz, which is the trap.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-shm-waves-85","question":"A sinusoidal wave of frequency 50 Hz and amplitude 2 mm travels on a string of linear density 0.04 kg/m under a tension of 100 N. The average power carried by the wave is about:","options":["0.79 W","0.20 W","0.39 W","3.9 W"],"answer":2,"explanation":"v = √(T/μ) = √(100/0.04) = 50 m/s, ω = 100π rad/s. P = ½μω²A²v = 0.5 × 0.04 × (100π)² × (2 × 10⁻³)² × 50 ≈ 0.39 W. Dropping the ½ gives 0.79 W.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-shm-waves-86","question":"For a particle executing simple harmonic motion, the magnitude of its acceleration is maximum:","options":["at the mean position, where its speed is maximum","at the extreme positions, where its speed is zero","midway between the mean and extreme positions","it is the same everywhere"],"answer":1,"explanation":"In SHM a = −ω²x, so |a| is largest where |x| is largest, i.e. at the extremes (where v = 0), and zero at the mean position.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-shm-waves-87","question":"A sound wave passes from air into water. Which of its properties stays the same?","options":["frequency","speed","wavelength","both speed and wavelength"],"answer":0,"explanation":"The frequency is fixed by the source: each crest arriving at the boundary produces one crest beyond it. The speed changes with the medium, so the wavelength λ = v/f changes too.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-shm-waves-88","question":"A 1 kg block on a smooth horizontal floor is connected to two walls by springs on either side, of constants 100 N/m and 300 N/m, both at their natural lengths. The period of small oscillations along the line of the springs is:","options":["2π/√75 s","π/5 s","π/20 s","π/10 s"],"answer":3,"explanation":"Displacing the block by x stretches one spring and compresses the other, and both forces oppose x: F = −(k₁ + k₂)x. So T = 2π√(m/(k₁ + k₂)) = 2π√(1/400) = π/10 ≈ 0.31 s. (They act in parallel, not in series.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-89","question":"A 1 kg block attached to a spring (k = 100 N/m) rests on a rough floor (μ_s = μ_k = 0.1, g = 10 m/s²). It is pulled 10 cm from the natural length and released. The total distance it travels before stopping is:","options":["100 cm","40 cm","50 cm","45 cm"],"answer":2,"explanation":"Kinetic friction μmg = 1 N shifts the equilibrium by 1 cm, so each half-swing reduces the amplitude about the natural length by 2 cm: 10 → 8 → 6 → 4 → 2 → 0 cm. Distance = 18 + 14 + 10 + 6 + 2 = 50 cm, and it stops exactly at natural length. Check: ½kx₀² = 0.5 J = μmg × 0.5 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-90","question":"A 1 kg block is at rest on a smooth floor, attached to a wall by a spring of constant 200 N/m at its natural length. A 1 kg lump of putty moving at 2 m/s along the spring's axis hits it and sticks. The amplitude of the resulting oscillation is:","options":["20 cm","14.1 cm","10 cm","7.1 cm"],"answer":2,"explanation":"Momentum: the pair moves at 1 m/s just after impact, at the equilibrium position. With ω = √(200/2) = 10 rad/s, the amplitude is v/ω = 0.1 m = 10 cm. Using the putty's initial energy instead would ignore the inelastic loss.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-91","question":"A 1 kg block slides at 2 m/s on a smooth floor between two identical springs (k = 400 N/m) fixed to opposite walls. The free ends of the springs are 2 m apart, so the block moves freely between them and bounces off each spring. The period of this periodic motion is:","options":["(2 + π/20) s","(2 + π/10) s","π/10 s","(1 + π/10) s"],"answer":1,"explanation":"Each pass across the 2 m gap takes 1 s, and there are two per cycle: 2 s. Each spring contact is half an oscillation of period 2π√(m/k) = π/10 s, so lasts π/20 s; two contacts add π/10 s. Total = 2 + π/10 ≈ 2.31 s. The motion is periodic but not simple harmonic.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-92","question":"A simple pendulum with a solid bob of density 4000 kg/m³ has period T in air. If it oscillates with the bob completely immersed in water (density 1000 kg/m³), neglecting viscous drag, its period becomes:","options":["2T/√3 ≈ 1.15T","√3T/2 ≈ 0.87T","T","4T/3"],"answer":0,"explanation":"Buoyancy reduces the effective weight, so g_eff = g(1 − ρ_w/ρ_bob) = 3g/4 while the inertia is unchanged. T ∝ 1/√g_eff, so T′ = T√(4/3) ≈ 1.15T.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-93","question":"A thin uniform ring of radius 0.5 m hangs on a horizontal nail passing over its rim, and swings with small amplitude in its own plane (g = 10 m/s²). Its period is about:","options":["2.81 s","1.40 s","1.72 s","1.99 s"],"answer":3,"explanation":"For a physical pendulum T = 2π√(I/(Mgd)). About a point on the rim, I = MR² + MR² = 2MR², and d = R. So T = 2π√(2R/g) = 2π√0.1 ≈ 1.99 s, the same as a simple pendulum of length equal to the diameter.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-94","question":"A uniform disc of radius R is made to oscillate as a physical pendulum in its own vertical plane about a horizontal axis perpendicular to the disc. For the period to be the minimum possible, the axis should be at a distance from the centre of:","options":["R/√3","R/2","R","R/√2"],"answer":3,"explanation":"T = 2π√[(k² + d²)/(gd)] with k² = R²/2 about the centre. (k² + d²)/d is minimised when d = k = R/√2, giving T_min = 2π√(2k/g).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-95","question":"A particle executes SHM of period T. The time between two successive instants at which its kinetic energy equals its potential energy is:","options":["T/2","T/8","T/4","T/6"],"answer":2,"explanation":"KE = PE at x = ±A/√2, i.e. at phases π/4, 3π/4, 5π/4, … These are spaced π/2 apart, which corresponds to a time T/4.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-96","question":"For a sinusoidal wave y = A sin(kx − ωt) on a string, the maximum speed of a particle of the string equals the wave speed when:","options":["A = λ","A = λ/2π","A = λ/4","A = 2πλ"],"answer":1,"explanation":"Maximum particle speed = Aω; wave speed = ω/k. Equality gives A = 1/k = λ/2π. Typically A ≪ λ/2π, so the particles move much more slowly than the wave.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-97","question":"Two strings under the same tension are joined end to end and stretched between fixed supports. String 1 is 0.6 m long with wave speed 120 m/s; string 2 is 0.4 m long with four times the linear mass density. The lowest frequency of a standing wave with a node at the junction is:","options":["300 Hz","100 Hz","75 Hz","150 Hz"],"answer":0,"explanation":"String 2's wave speed is 120/√4 = 60 m/s. Each segment must hold a whole number of loops: f = n₁ × 120/(2 × 0.6) = 100n₁ and f = n₂ × 60/(2 × 0.4) = 75n₂. The smallest common value is 300 Hz (n₁ = 3, n₂ = 4).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-98","question":"A source emitting sound of frequency f moves at constant speed along a straight road; a stationary listener stands some distance from the road. At the instant the source is at its point of closest approach to the listener, the frequency the listener hears is:","options":["higher than f","exactly f","lower than f","zero"],"answer":0,"explanation":"The sound reaching the listener at that instant was emitted earlier, while the source was still approaching (with a velocity component towards the listener). So the heard frequency is still above f; the exact f is heard slightly later, from sound emitted at the closest point.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-99","question":"A small source radiates sound uniformly in all directions. The sound level at 10 m from it is 80 dB. Neglecting absorption, the level at 100 m is:","options":["40 dB","8 dB","70 dB","60 dB"],"answer":3,"explanation":"Intensity ∝ 1/r², so going 10 times farther reduces the intensity 100-fold. Each factor of 10 in intensity is 10 dB, so the level drops by 20 dB, to 60 dB.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-100","question":"At the open end of an organ pipe sounding a standing wave, which statement is correct?","options":["It is a node of both displacement and pressure","It is a displacement node and a pressure antinode","It is a displacement antinode and a pressure node","It is an antinode of both displacement and pressure"],"answer":2,"explanation":"The pressure at an open end is pinned at atmospheric, so the pressure variation is zero (a pressure node). Pressure and displacement variations are 90° out of step in space, so this is where air moves most: a displacement antinode.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-101","question":"A 0.5 kg particle moves along the x-axis in a potential U(x) = U₀(1 − cos ax), with U₀ = 2 J and a = 5 m⁻¹. The period of its small oscillations about x = 0 is:","options":["π/10 s","π/5 s ≈ 0.63 s","2π/5 s","π s"],"answer":1,"explanation":"For small x, U ≈ U₀a²x²/2, an effective spring constant k = U₀a² = 50 N/m. So ω = √(k/m) = √100 = 10 rad/s and T = 2π/10 = π/5 ≈ 0.63 s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-102","question":"A 1 kg block hangs from a light string that passes over a pulley (a uniform disc of mass 2 kg, free to turn on a frictionless axle) and is tied at its other end to a vertical spring of constant 50 N/m fixed to the floor. The string does not slip. The period of small vertical oscillations of the block is:","options":["0.2π s ≈ 0.63 s","0.4π s ≈ 1.26 s","0.2√2 π s ≈ 0.89 s","0.4√2 π s ≈ 1.78 s"],"answer":1,"explanation":"Energy: ½mv² + ½I(v/R)² + ½kx² with I/R² = M/2 = 1 kg gives an effective mass m + M/2 = 2 kg (gravity only shifts the equilibrium). T = 2π√(2/50) = 2π × 0.2 = 0.4π ≈ 1.26 s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-103","question":"A block attached to a spring oscillates first on a smooth horizontal surface, then on a smooth incline of 30°, and then hanging vertically. Its period of oscillation:","options":["is the same in all three cases","is largest when hanging vertically","is largest on the incline","is smallest when hanging vertically"],"answer":0,"explanation":"Gravity (or its component along the incline) is a constant force; it only shifts the equilibrium position. The restoring force about the new equilibrium is still −kx, so T = 2π√(m/k) in every case.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-104","question":"A small solid ball rolls without slipping, back and forth, near the bottom of a large fixed spherical bowl of radius 1.4 m (the ball's radius is negligible compared with the bowl's; g = 10 m/s²). The period of these small oscillations is about:","options":["3.29 s","2.35 s","1.97 s","2.78 s"],"answer":3,"explanation":"Rolling adds rotational inertia: the ball's KE is (7/10)mv². For small angles the equation becomes (7/5)ẍ = −(g/R)x, so T = 2π√(7R/5g) = 2π√0.196 ≈ 2.78 s. A sliding (frictionless) particle would have 2π√(R/g) ≈ 2.35 s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-105","question":"A 2 kg block is attached to the lower end of a light vertical spring (k = 200 N/m) and released from rest with the spring at its natural length (g = 10 m/s²). The maximum force exerted by the spring during the motion is:","options":["80 N","20 N","40 N","10 N"],"answer":2,"explanation":"The equilibrium extension is mg/k = 0.1 m, and released from natural length the block oscillates with amplitude 0.1 m about it. Maximum extension = 0.2 m, so the maximum spring force is 200 × 0.2 = 40 N = 2mg.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-106","question":"A wave pulse on a string is described by y = 4/[2 + (3x + 6t)²], with x, y in metres and t in seconds. The pulse moves:","options":["along −x at 6 m/s","along +x at 2 m/s","along −x at 2 m/s","along +x at 0.5 m/s"],"answer":2,"explanation":"Write 3x + 6t = 3(x + 2t). Any function of (x + vt) is a shape moving along −x at speed v, so the pulse travels in the negative x-direction at 2 m/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-107","question":"A string fixed at both ends, 1 m long, is plucked at a point 25 cm from one end and released. Which of these harmonics is absent from the resulting vibration?","options":["the 2nd harmonic","the 4th harmonic","the 3rd harmonic","the 5th harmonic"],"answer":1,"explanation":"The plucked point is displaced, so it must be an antinode-like region, and any harmonic with a node at 25 cm (L/4) cannot be excited. The nth harmonic has nodes at multiples of L/n; L/4 is a node for n = 4, 8, 12, … but not for n = 2, 3 or 5.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-108","question":"Two loudspeakers driven in phase by the same oscillator are placed so that a listener is 4 m from one and 5 m from the other. Taking the speed of sound as 340 m/s, the lowest frequency for which the listener hears a minimum is:","options":["170 Hz","340 Hz","85 Hz","510 Hz"],"answer":0,"explanation":"For in-phase sources, a minimum needs a path difference of (n + ½)λ. Here the path difference is 1 m, so the largest λ satisfying it is λ = 2 m, i.e. f = 340/2 = 170 Hz.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-109","question":"A 1 kg block on a smooth floor oscillates horizontally on a spring with amplitude 10 cm. As it passes through the mean position, a 1 kg lump of putty is dropped vertically onto it and sticks. The new amplitude is about:","options":["14.1 cm","5 cm","10 cm","7.1 cm"],"answer":3,"explanation":"Horizontal momentum is conserved, so the speed halves: v′ = v/2. The new ω′ = ω/√2. Amplitude = v′/ω′ = (v/2)(√2/ω) = A/√2 ≈ 7.1 cm. (Had the putty landed at an extreme, the amplitude would not change.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-110","question":"A steel wire 0.5 m long is clamped between two rigid supports with no tension at 40 °C. It is cooled to −10 °C. Taking Y = 2 × 10¹¹ N/m², α = 1.2 × 10⁻⁵ K⁻¹ and density 8000 kg/m³, its fundamental frequency of transverse vibration is about:","options":["387 Hz","245 Hz","61 Hz","122 Hz"],"answer":3,"explanation":"Cooling with fixed ends creates a tensile stress YαΔT = 2 × 10¹¹ × 1.2 × 10⁻⁵ × 50 = 1.2 × 10⁸ Pa. Wave speed = √(T/μ) = √(stress/ρ) = √(1.5 × 10⁴) ≈ 122.5 m/s. f₁ = v/2L ≈ 122 Hz.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-111","question":"Newton calculated the speed of sound in air assuming isothermal compressions and got about 280 m/s, well below the measured value. Laplace's correction is that:","options":["sound travels as a transverse wave","the density of air is lower than Newton assumed","the compressions are adiabatic, so the bulk modulus is γP instead of P","the compressions are isothermal but the temperature is higher"],"answer":2,"explanation":"The compressions and rarefactions are too rapid for heat to flow, so they are adiabatic. The relevant bulk modulus becomes γP, raising the speed by √γ ≈ 1.18, to about 330 m/s at 0 °C.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-112","question":"A car moves at 5 m/s straight towards a large flat wall, sounding a 680 Hz horn. A stationary listener stands on the road behind the car. Taking the speed of sound as 340 m/s, the number of beats per second the listener hears between the direct sound and the echo is about:","options":["10","20","40","zero"],"answer":1,"explanation":"Direct sound (source receding): f₁ = 680 × 340/345. Echo: the wall receives 680 × 340/335 and reflects it unchanged to the stationary listener. Beat frequency = 680 × 340(1/335 − 1/345) ≈ 20 Hz (≈ 2fu/v).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-113","question":"A sonometer wire vibrating in its fundamental mode is in unison with a 300 Hz tuning fork. The tension in the wire is increased by 2%. The number of beats heard per second is now about:","options":["3","6","1.5","9"],"answer":0,"explanation":"f ∝ √T, so a 2% increase in tension raises f by about 1%: Δf ≈ 300 × 0.01 = 3 Hz. Hence about 3 beats per second.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-114","question":"A transverse wave travels along a string at 200 m/s. At a certain instant, the slope of the string at a point is 0.01. The transverse speed of the string at that point at that instant is:","options":["2 m/s","0.02 m/s","200 m/s","20 m/s"],"answer":0,"explanation":"For a travelling wave y = f(x − vt), ∂y/∂t = −v ∂y/∂x. So |v_particle| = v × |slope| = 200 × 0.01 = 2 m/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-shm-waves-115","question":"A man stands between two parallel cliffs and claps once. He hears the first echo after 1 s and the second after 2 s. Taking the speed of sound as 340 m/s, the distance between the cliffs is:","options":["255 m","1020 m","340 m","510 m"],"answer":3,"explanation":"The echo from each cliff travels there and back: distances 340 × 1/2 = 170 m and 340 × 2/2 = 340 m. The cliffs are 170 + 340 = 510 m apart.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-116","question":"A 2 kg block rests on a smooth cart and is attached to the front wall of the cart by a spring (k = 200 N/m) at its natural length. The cart suddenly starts moving forward with a constant acceleration of 5 m/s². In the cart's frame, the amplitude of the block's oscillation is:","options":["2.5 cm","10 cm","5 cm","zero"],"answer":2,"explanation":"In the cart frame a pseudo-force ma = 10 N acts backward, shifting the equilibrium by ma/k = 0.05 m. The block starts at rest at the old position, which is an extreme of the new motion, so the amplitude is 5 cm (and the period is unchanged).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-shm-waves-117","question":"A uniform solid cylinder of mass 2 kg rolls without slipping on a horizontal floor, its axle attached to a horizontal spring of constant 300 N/m. The period of its small oscillations is:","options":["0.16π s","0.2π s ≈ 0.63 s","0.23π s","0.4π s"],"answer":1,"explanation":"Energy: ½mv² + ½(½mR²)(v/R)² + ½kx² = ¾mv² + ½kx², so the effective mass is 3m/2 = 3 kg. T = 2π√(3/300) = 2π × 0.1 = 0.2π ≈ 0.63 s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-shm-waves-118","question":"A metal wire is stretched so that its longitudinal strain is 1 × 10⁻⁴. The ratio of the speed of transverse waves on it to the speed of longitudinal waves in it is:","options":["1 × 10⁻⁴","0.01","100","0.1"],"answer":1,"explanation":"Transverse: v_t = √(T/μ) = √(stress/ρ). Longitudinal: v_l = √(Y/ρ). Ratio = √(stress/Y) = √strain = √10⁻⁴ = 0.01.","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
